  // ── ՕԺԱՆԴԱԿ ՖՈՒՆԿՑԻԱՆԵՐ ──────────────────────────────────────────
  
  export function getLitThemeById(id) {
    return literatureThemes.find((t) => t.id === id) || null;
  }
  
  export function getHistTopicById(id) {
    return historyTopics.find((t) => t.id === id) || null;
  }
  
  export function getRelatedHistoryTopics(litTheme) {
    return (litTheme.relatedHistoryIds || [])
      .map((id) => getHistTopicById(id))
      .filter(Boolean);
  }
  
  export function getRelatedLiteratureThemes(histTopic) {
    return (histTopic.relatedLiteratureIds || [])
      .map((id) => getLitThemeById(id))
      .filter(Boolean);
  }